action.code:
// Check if bounding boxes intersect first for quick rejection
if (!P1.bb().intersects(P2.bb()))
    return false;

// Separating Axis Theorem implementation
auto getEdges = [](const cg3::Polygon2& poly) {
    std::vector<cg3::Point2d> edges;
    for (size_t i = 0; i < poly.size(); ++i) {
        size_t j = (i + 1) % poly.size();
        edges.push_back(poly[i] - poly[j]);
        edges.back().normalize();
    }
    return edges;
};

auto getNormals = [](const std::vector<cg3::Point2d>& edges) {
    std::vector<cg3::Point2d> normals;
    for (const auto& edge : edges) {
        normals.push_back(cg3::Point2d(-edge.y(), edge.x()));
    }
    return normals;
};

auto projectPolygon = [](const cg3::Polygon2& poly, const cg3::Point2d& axis) {
    double min = axis.dot(poly[0]);
    double max = min;
    for (size_t i = 1; i < poly.size(); ++i) {
        double proj = axis.dot(poly[i]);
        if (proj < min) min = proj;
        if (proj > max) max = proj;
    }
    return std::make_pair(min, max);
};

auto edges1 = getEdges(P1);
auto edges2 = getEdges(P2);
auto normals1 = getNormals(edges1);
auto normals2 = getNormals(edges2);

// Combine all potential separating axes
std::vector<cg3::Point2d> axes;
axes.insert(axes.end(), normals1.begin(), normals1.end());
axes.insert(axes.end(), normals2.begin(), normals2.end());

// Check for overlap on each axis
for (const auto& axis : axes) {
    auto [min1, max1] = projectPolygon(P1, axis);
    auto [min2, max2] = projectPolygon(P2, axis);

    if (max1 < min2 || max2 < min1)
        return false;
}

return true;

